{
    u8 level;
    s32 bright;

    if (persona == NULL) {
        return;
    }
    level = *((u8*)persona + 4);
    bright = campPersonaClampFade(fade);
    if (level < 10) {
        campPersonaDrawDigit(alpha, x + 75.0f, y + 127.0f, level);
    } else {
        campPersonaDrawDigit(alpha, x + 67.0f, y + 127.0f, level / 10);
        campPersonaDrawDigit(alpha, x + 82.0f, y + 127.0f, level % 10);
    }
}

