// FUN_00128480
void h_campStatusDrawStatLabels(CampVec2 position, f32 scale, void* persona,
                                s32 alpha)
{
    u32 parent;
    u32 i;
    s32 value;
    s32 frame;
    f32 x;
    f32 y;

    x = position.x + 32.0f;
    y = position.y + 72.0f;
    for (i = 0; i < 9; i++) {
        switch (i) {
        case 0:
            value = FUN_001733b0_s32(persona, 0);
            break;
        case 1:
            value = FUN_001733b0_s32(persona, 1);
            break;
        case 2:
            value = FUN_001733b0_s32(persona, 2);
            break;
        case 3:
            value = FUN_001733b0_s32(persona, 3);
            break;
        case 4:
            value = FUN_001733b0_s32(persona, 4);
            break;
        case 5:
            value = FUN_001733b0_s32(persona, 5);
            break;
        case 6:
            value = FUN_001733b0_s32(persona, 6);
            break;
        case 7:
            value = FUN_001733b0_s32(persona, 8);
            break;
        case 8:
            value = FUN_001733b0_s32(persona, 9);
            break;
        }
        frame = 15;
        if ((value & 0x4000000) != 0) {
            frame = 13;
        }
        else if ((value & 0x2000000) != 0) {
            frame = 14;
        }
        else if ((value & 0x1000000) != 0) {
            frame = 12;
        }
        else if ((value & 0x10000000) != 0) {
            frame = 11;
        }
        else if ((value & 0x8000000) != 0) {
            frame = 10;
        }
        campStatusDrawSpriteCall(parent, *(void**)DAT_00833B98_abs, frame, (u8)alpha,
                                 x, y, scale);
        if (i == 2) {
            x = 162.0f;
        }
        else {
            x += 40.0f;
        }
    }
}

